game = ConnectKGame(2, 2, 3)
for call in (lambda: game.make_move(Player.O, 0), lambda: game.make_move(Player.X, -1), lambda: game.make_move(Player.X, 2)):
    try:
        call()
        raise AssertionError('expected ValueError')
    except ValueError:
        pass
assert game.make_move(Player.X, 0) is GameStatus.IN_PROGRESS
assert game.make_move(Player.O, 0) is GameStatus.IN_PROGRESS
try:
    game.make_move(Player.X, 0)
    raise AssertionError('expected ValueError')
except ValueError:
    pass
